<?php $statusOrder = ['received', 'approved', 'shipped', 'delivered']; $currentStep = array_search($order['status'], $statusOrder, true); ?>
<?= view('components/page_start', ['pageTitle' => $pageTitle]) ?>
<section class="page-section"><div class="container-xl"><div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-5"><div><p class="eyebrow">Order tracking</p><h1 class="section-title mb-0">Order #<?= esc($orderId) ?></h1></div><span class="badge rounded-pill text-bg-warning px-3 py-2"><?= esc(ucfirst($order['status'])) ?></span></div><div class="surface-card p-4 p-md-5 mb-4"><div class="row g-4 justify-content-between"><?php foreach ($statusOrder as $index => $status): ?><div class="col order-step <?= $currentStep !== false && $index <= $currentStep ? 'active' : '' ?>"><?= esc(ucfirst($status)) ?></div><?php endforeach; ?></div></div><div class="surface-card p-4"><?php foreach ($items as $item): ?><div class="d-flex align-items-center gap-3 py-3 border-bottom"><div class="cart-thumb"><i class="fa-solid fa-gift"></i></div><div class="flex-grow-1"><strong><?= esc($item['product_name']) ?></strong><span class="d-block text-muted-brand"><?= $item['variant'] ? esc($item['variant']) . ' · ' : '' ?>Qty <?= esc($item['quantity']) ?></span></div><strong>₱<?= number_format($item['line_total'], 2) ?></strong></div><?php endforeach; ?><div class="d-flex justify-content-end gap-4 pt-4"><strong>Total</strong><strong>₱<?= number_format($order['total'], 2) ?></strong></div></div></div></section>
